package loop

// PacketLane is one running datagram lane (#852): a thread locked to it, its own
// io_uring, the socket's multishot RECVMSG and its replies' SENDMSG. StartPacket
// is the one way to get one.
//
// IFACE-OPAQUE: the lane is the leaf's; server drives its life cycle only.
type PacketLane interface {
	// Handover drains the socket before its successor reads it (ADR 0192 §D4):
	// the lane stops its receive, serves what the socket queued to EAGAIN,
	// sends the replies, switches UDP GRO off and stops; Done is closed then.
	Handover()
	// Stop stops the lane now, its queued datagrams left in the socket, and
	// waits until its thread has returned.
	Stop()
	// Done is closed once the lane's thread has returned.
	Done() <-chan struct{}
}
